import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:strict_proxy_client/features/engine/bundle_verifier.dart';

/// The controller signs canonical JSON; this client must reproduce those exact
/// bytes. The fixtures are generated by the controller's own signer
/// (`test/tools/emit-canonical-fixtures.ts`), so this pins the Dart mirror to
/// reality rather than to a hand-written guess.
void main() {
  // Loaded at runtime: JSON cannot be imported as a Dart library.
  late String publicKeyBase64;
  late List<dynamic> fixtures;

  setUpAll(() {
    final raw = jsonDecode(File('test/canonical_fixtures.json').readAsStringSync()) as Map<String, dynamic>;
    publicKeyBase64 = raw['publicKeyBase64'] as String;
    fixtures = raw['fixtures'] as List<dynamic>;
  });

  BundleVerifier verifier() => BundleVerifier(publicKeyBytes: base64Decode(publicKeyBase64));

  group('canonical JSON', () {
    test('matches the controller byte for byte', () {
      for (final entry in fixtures) {
        final f = entry as Map<String, dynamic>;
        expect(
          BundleVerifier.canonicalJson(f['payload']),
          f['canonical'] as String,
          reason: 'canonical JSON must match the controller exactly',
        );
      }
    });

    test('sorts object keys', () {
      expect(BundleVerifier.canonicalJson({'b': 1, 'a': 2}), '{"a":2,"b":1}');
      expect(BundleVerifier.canonicalJson({'z': 1, 'A': 2}), '{"A":2,"z":1}');
    });

    test('renders primitives the way JSON does', () {
      expect(BundleVerifier.canonicalJson(null), 'null');
      expect(BundleVerifier.canonicalJson(true), 'true');
      expect(BundleVerifier.canonicalJson(false), 'false');
      expect(BundleVerifier.canonicalJson('hi'), '"hi"');
      expect(BundleVerifier.canonicalJson(443), '443');
      expect(BundleVerifier.canonicalJson(1.5), '1.5');
    });

    test('renders nested arrays and objects', () {
      expect(BundleVerifier.canonicalJson([1, 'a', null, true]), '[1,"a",null,true]');
      expect(BundleVerifier.canonicalJson({'b': {'d': 1, 'c': 2}}), '{"b":{"c":2,"d":1}}');
    });

    test('escapes strings', () {
      expect(BundleVerifier.canonicalJson({'a': 'say "hi"'}), '{"a":"say \\"hi\\""}');
    });
  });

  group('verification', () {
    test('accepts every real fixture', () async {
      final v = verifier();
      for (final entry in fixtures) {
        final f = entry as Map<String, dynamic>;
        final ok = await v.verify(f['payload'] as Map<String, dynamic>, f['signature'] as String);
        expect(ok, isTrue, reason: 'a genuine signature must verify');
      }
    });

    test('rejects a tampered payload', () async {
      final v = verifier();
      final f = fixtures.first as Map<String, dynamic>;
      final tampered = Map<String, dynamic>.from(f['payload'] as Map<String, dynamic>);
      // Move a node to a different address.
      tampered['nodes'] = [
        {'id': 'n1', 'publicIp': '203.0.113.99', 'loadScore': 0, 'status': 'online'},
      ];
      expect(await v.verify(tampered, f['signature'] as String), isFalse);
    });

    test('rejects a signature from a different key', () async {
      final other = BundleVerifier(publicKeyBytes: List<int>.filled(32, 7));
      final f = fixtures.first as Map<String, dynamic>;
      expect(await other.verify(f['payload'] as Map<String, dynamic>, f['signature'] as String), isFalse);
    });

    test('rejects a malformed signature without throwing', () async {
      final v = verifier();
      final f = fixtures.first as Map<String, dynamic>;
      for (final bad in ['', 'not-base64!!!', '####', 'AAAA']) {
        expect(await v.verify(f['payload'] as Map<String, dynamic>, bad), isFalse, reason: bad);
      }
    });

    test('rejects everything when the key is unusable', () async {
      final f = fixtures.first as Map<String, dynamic>;
      for (final key in [const <int>[], List<int>.filled(31, 1), List<int>.filled(33, 1)]) {
        final v = BundleVerifier(publicKeyBytes: key);
        expect(v.isUsable, isFalse);
        expect(await v.verify(f['payload'] as Map<String, dynamic>, f['signature'] as String), isFalse);
      }
    });

    test('is not fooled by reordering the JSON keys', () async {
      final v = verifier();
      final f = fixtures.last as Map<String, dynamic>;
      final payload = f['payload'] as Map<String, dynamic>;
      // Same data, different insertion order: canonical form is unchanged, so
      // the signature must still verify.
      final reordered = <String, dynamic>{
        'configs': payload['configs'],
        'nodes': payload['nodes'],
        'expiresAt': payload['expiresAt'],
      };
      expect(await v.verify(reordered, f['signature'] as String), isTrue);
    });
  });
}